      function quotaWindowName(name){return({five_hour:'5 小时',five_hours:'5 小时',daily:'每日',seven_day:'7 天',seven_day_sonnet:'Sonnet 7 天',seven_day_opus:'Opus 7 天',weekly:'每周',monthly:'每月'}[String(name||'').toLowerCase()]||String(name||'Usage'))}
      function usagePercent(value){if(!value||typeof value!=='object')return null;var used=Number(value.used_percent);if(Number.isFinite(used))return Math.max(0,Math.min(100,used));var remaining=Number(value.remaining_percent);if(Number.isFinite(remaining))return Math.max(0,Math.min(100,100-remaining));var usedCount=value.used;if(usedCount==null)usedCount=value.used_count;if(usedCount==null)usedCount=value.used_tokens;var remainingCount=value.remaining;if(remainingCount==null)remainingCount=value.remaining_count;if(remainingCount==null)remainingCount=value.remaining_tokens;if(remainingCount==null)remainingCount=value.balance;var limit=value.limit;if(limit==null)limit=value.total;if(limit==null)limit=value.cap;if(usedCount==null&&remainingCount!=null&&limit!=null)usedCount=Number(limit)-Number(remainingCount);if(Number.isFinite(Number(usedCount))&&Number(limit)>0)return Math.max(0,Math.min(100,Number(usedCount)/Number(limit)*100));return null}
