      function renderAccounts(){var query=$('accountSearch').value.trim().toLowerCase();var provider=$('providerFilter').value;var filtered=accounts.filter(function(a){return(!provider||a.provider===provider)&&(!query||(a.name+' '+a.provider).toLowerCase().includes(query))});if(!filtered.length){$('accountTable').innerHTML='<div class="empty">'+(accounts.length?'没有匹配的账号。':'暂无账号。先接入一个上游订阅吧。')+'</div>';return}$('accountTable').innerHTML='<table><thead><tr><th>账号</th><th>平台</th><th>状态</th><th>Usage</th><th>24h 请求</th><th>Token</th><th style="text-align:right">操作</th></tr></thead><tbody>'+filtered.map(function(a){var enabled=a.enabled!==false;return '<tr><td><div class="account-name">'+escapeHTML(a.name||'未命名账号')+'</div><div class="subtle">ID '+escapeHTML(a.id)+'</div></td><td><div class="provider-name">'+providerIcon(a.provider)+escapeHTML(a.provider||'—')+'</div></td><td><span class="badge '+(enabled?'ok':'off')+'"><span class="dot" style="background:'+(enabled?'var(--green)':'#748196')+'"></span>'+(enabled?'已启用':'已停用')+'</span></td><td><div class="quota-unknown"><span class="badge warn">未知</span><small>当前 API 未提供 Usage</small></div></td><td>—</td><td>—</td><td><div class="actions">'+iconActionButton('edit',a.id,'编辑','edit')+iconActionButton('delete',a.id,'删除','trash','btn-danger')+'</div></td></tr>'}).join('')+'</tbody></table>'}
      function setAccountModalMode(account){editingAccountID=account?account.id:0;var editing=!!editingAccountID;document.querySelectorAll('#accountForm .create-only').forEach(function(el){el.hidden=editing});document.querySelectorAll('#accountForm .edit-only').forEach(function(el){el.hidden=!editing});$('accountProvider').disabled=editing;$('authType').disabled=editing;$('accountModalTitle').textContent=editing?'编辑账号':'接入上游账号';$('deleteAccountButton').hidden=!editing;$('authorizeButton').hidden=editing;$('refreshUsageButton').hidden=!(editing&&canRefreshUsage(account));$('clearProxyField').hidden=!(editing&&account&&account.proxy_configured);$('clearProxy').checked=false;$('proxyHint').textContent=editing&&account&&account.proxy_configured?'已配置代理。留空保持不变，勾选下方选项可清除。':'代理地址以明文保存，管理 API 不会回显。';updateCredentialHint()}
