      function prettyJSON(value){if(value==null||value==='')return'';if(typeof value==='string'){try{return JSON.stringify(JSON.parse(value),null,2)}catch(e){return value}}try{return JSON.stringify(value,null,2)}catch(e){return''}}
      async function openEditAccount(account){$('accountForm').reset();$('accountName').value=account.name;$('accountProvider').value=account.provider;$('authType').value=account.config&&account.config.credential_id?'oauth':'api_key';$('accountEnabled').value='1';$('concurrencyLimit').value='1';$('concurrencyQueueTimeoutSeconds').value='0';$('proxyURL').value='';$('credentials').value=prettyJSON(account.config);setAccountModalMode(account);$('accountModal').hidden=false;$('accountName').focus()}
      function closeAccountModal(){editingAccountID=0;$('accountModal').hidden=true}
      function updateCredentialHint(){var editing=!!editingAccountID;var p=$('accountProvider').value;var auth=$('authType').value;var webLogin=!editing&&auth==='oauth'&&(p==='grok'||p==='claude'||p==='codex');$('credentials').required=!webLogin;$('credentials').disabled=webLogin;;if(editing){$('credentials').placeholder='{"access_token":"..."}';$('credentialHint').textContent='保存修改时会写入当前 JSON。';$('createButton').textContent='保存修改';return}if(p==='grok'&&auth==='oauth'&&!editing){$('credentials').placeholder='由 xAI OAuth 登录自动填写';$('credentialHint').textContent='提交后会显示 xAI 设备授权码，登录成功后自动保存并续期 Token。';$('createButton').textContent='完成'}else if(p==='claude'&&auth==='oauth'&&!editing){$('credentials').placeholder='由 Claude 网页登录自动填写';$('credentialHint').textContent='提交后会打开 Claude 官方授权页。登录完成后把授权码粘贴回来，Token 会自动保存并续期。';$('createButton').textContent='完成'}else if(p==='codex'&&auth==='oauth'&&!editing){$('credentials').placeholder='由 Codex 网页登录自动填写';$('credentialHint').textContent='提交后会打开 ChatGPT 官方授权页。完成后把回调 URL 粘贴回来，Token 会自动保存并续期。';$('createButton').textContent='完成'}else if(auth==='api_key'){$('credentials').placeholder='{"api_key":"..."}';$('credentialHint').textContent='填入上游平台 API Key。';$('createButton').textContent='创建账号'}else{$('credentials').placeholder='{"access_token":"...","refresh_token":"..."}';$('credentialHint').textContent='凭据以明文保存。';$('createButton').textContent='创建账号'}}
      function accountFormPayload(){var payload={name:$('accountName').value.trim(),concurrency_limit:Number($('concurrencyLimit').value)||1,concurrency_queue_timeout_seconds:Number($('concurrencyQueueTimeoutSeconds').value)||0};if($('proxyURL').value.trim())payload.proxy_url=$('proxyURL').value.trim();return payload}
      function hasOAuthCredential(){return oauthAuthorized||(!$('credentials').disabled&&$('credentials').value.trim()!=='')}
      async function saveAccount(event,startOAuth){event.preventDefault();if(startOAuth&&$('authType').value==='oauth'&&$('accountProvider').value==='dummy')$('credentials').disabled=true;if(!$('accountForm').checkValidity()){$('accountForm').reportValidity();return}if(editingAccountID){try{var editPayload={name:$('accountName').value.trim(),provider:$('accountProvider').value,config:JSON.parse($('credentials').value||'{}')};await request('/api/providers/'+encodeURIComponent(editingAccountID),{method:'PUT',body:JSON.stringify(editPayload)});closeAccountModal();toast('账号已更新');await loadData();return}catch(e){toast(e.message,true);return}}if(!startOAuth&&!oauthAuthorized&&$('authType').value==='oauth'&&!hasOAuthCredential()){$('credentialHint').textContent='请先点击权鉴完成 OAuth 授权。';toast('请先点击权鉴完成 OAuth 授权',true);return}var button=$('createButton');button.disabled=true;try{var provider=$('accountProvider').value;var auth=$('authType').value;var payload=accountFormPayload();if(startOAuth&&auth==='oauth'&&!oauthAuthorized&&(provider==='grok'||provider==='dummy'||provider==='claude'||provider==='codex')){if(provider==='grok'||provider==='dummy'){grokOAuthProvider=provider;configureDeviceOAuthModal(provider);$('grokOAuthModal').hidden=false;$('grokOAuthCode').textContent='—';$('grokOAuthStatus').textContent=grokOAuthProvider==='dummy'?'正在准备 Dummy 模拟授权…':'正在向 xAI 申请登录码…';$('grokOAuthOpen').href='#';var started=await request('/api/oauth/'+encodeURIComponent(grokOAuthProvider)+'/start',{method:'POST',body:'{}'});grokOAuthFlowID=started.session_id;$('grokOAuthCode').textContent=started.user_code||'—';$('grokOAuthOpen').href=started.verification_uri;$('grokOAuthStatus').textContent=grokOAuthProvider==='dummy'?'Dummy 模拟授权已准备，本页会自动查询结果。':'请打开授权页面并完成授权，本页会自动查询权鉴结果。';scheduleGrokOAuthPoll(5000);return}await startPKCEOAuth(provider,payload);return}payload.provider=provider;try{payload.config=JSON.parse($('credentials').value)}catch(e){toast('权鉴凭据 JSON 无效',true);return}await request('/api/providers',{method:'POST',body:JSON.stringify(payload)});closeAccountModal();toast('账号已创建，请到 API Key 页面签发调用密钥');await loadData()}catch(e){$('grokOAuthModal').hidden=true;$('pkceOAuthModal').hidden=true;toast(e.message,true)}finally{button.disabled=false}}
      function scheduleGrokOAuthPoll(delay){clearTimeout(grokOAuthTimer);if(!grokOAuthFlowID)return;grokOAuthTimer=setTimeout(pollGrokOAuth,Math.max(1000,delay||5000))}
      async function pollGrokOAuth(){if(!grokOAuthFlowID)return;try{var result=await request('/api/oauth/'+encodeURIComponent(grokOAuthProvider)+'/poll/'+encodeURIComponent(grokOAuthFlowID),{method:'POST',body:'{}'});if(result.status==='complete'){await loadOAuthResult(result);grokOAuthFlowID='';$('grokOAuthModal').hidden=true;toast(grokOAuthProvider==='dummy'?'Dummy 权鉴成功，请点击完成保存订阅':'Grok 权鉴成功，请点击完成保存订阅');await loadData();return}$('grokOAuthStatus').textContent=grokOAuthProvider==='dummy'?'Dummy 授权处理中…':'等待你在 xAI 页面确认授权…';scheduleGrokOAuthPoll((Number(result.interval_seconds)||5)*1000)}catch(e){grokOAuthFlowID='';$('grokOAuthModal').hidden=true;toast(e.message,true)}}
      function configureDeviceOAuthModal(provider){var dummy=provider==='dummy';var modal=$('grokOAuthModal');modal.querySelector('.modal-head h2').textContent=dummy?'登录 Dummy':'登录 Grok';modal.querySelector('.notice').textContent=dummy?'这是本地模拟 OAuth 流程，不会访问外部服务。':'请在 xAI 官方页面完成授权。UniSub 不会接触你的账号密码。';$('grokOAuthOpen').textContent=dummy?'模拟授权页面':'打开 xAI 授权页面';$('grokOAuthOpen').href=dummy?'#dummy-oauth':$('grokOAuthOpen').href}
