      function pkceProviderLabel(provider){return provider==='codex'?'Codex':(provider==='dummy'?'Dummy':'Claude')}
      function pkceStartPath(provider){return '/api/oauth/'+encodeURIComponent(provider)+'/start'}
      function pkceExchangePath(provider,sessionID){return '/api/oauth/'+encodeURIComponent(provider)+'/poll/'+encodeURIComponent(sessionID)}
      async function startPKCEOAuth(provider,payload){pkceOAuthFlowID='';pkceOAuthProvider=provider;$('pkceOAuthModal').hidden=false;$('pkceOAuthTitle').textContent='登录 '+pkceProviderLabel(provider);$('pkceOAuthNotice').textContent='请在 '+pkceProviderLabel(provider)+' 官方页面完成授权。UniSub 不会接触你的账号密码。';$('pkceOAuthOpen').href='#';$('pkceOAuthOpen').textContent='打开 '+pkceProviderLabel(provider)+' 授权页面';$('pkceOAuthCode').value='';$('pkceOAuthStatus').textContent='正在生成授权链接…';$('pkceOAuthHint').textContent=provider==='codex'?'授权完成后浏览器会跳转到 localhost:1455。即使页面打不开，也把地址栏完整 URL 粘贴到这里。':'授权完成后把官方页面显示的授权码完整粘贴到这里，包含 # 后面的部分。';var started=await request(pkceStartPath(provider),{method:'POST',body:'{}'});pkceOAuthFlowID=started.session_id;$('pkceOAuthOpen').href=started.authorization_url;$('pkceOAuthStatus').textContent='请打开官方页面登录，完成后返回本页面查询权鉴结果。'}
