      function cancelPKCEOAuth(){pkceOAuthFlowID='';pkceOAuthProvider='';oauthAuthorized=false;$('pkceOAuthModal').hidden=true;$('pkceOAuthCode').value=''}
      async function loadOAuthResult(result){if(!result||!result.result_id)return;var value=await request('/api/oauth/results/'+encodeURIComponent(result.result_id));var credential=value.result||value.credential||value;$('credentials').disabled=false;$('credentials').required=true;$('credentials').value=JSON.stringify({credential:credential},null,2);oauthAuthorized=true;$('credentialHint').textContent='权鉴结果已获取，请点击完成保存订阅。'}
