      function fillLogFilters(){}
      function pageSizeOptions(selected,sizes){return (sizes||[20,50,100,200]).map(function(size){return '<option value="'+size+'"'+(Number(selected)===size?' selected':'')+'>'+size+' 行/页</option>'}).join('')}
      function pageSizeSelectHTML(id,selected){return '<select id="'+id+'" title="每页行数" aria-label="每页行数">'+pageSizeOptions(selected,[20,50,100])+'</select>'}
      function syncLogPageSize(){var select=$('logPageSize');if(!select)return;var selected=Number(select.value);if(selected>0){logLimit=selected;return}select.value=String(logLimit)}
      function logQueryParams(){syncLogPageSize();var params=new URLSearchParams({page:String(Math.floor(logOffset/logLimit)+1),page_size:String(logLimit)});if($('logSearch').value.trim())params.set('q',$('logSearch').value.trim());return params}
      async function loadLogs(){fillLogFilters();try{var result=await request('/api/calls?'+logQueryParams());logs=result.items||[];logTotal=Number(result.total)||logs.length;logOffset=Math.floor(logOffset/logLimit)*logLimit;renderLogs()}catch(e){toast(e.message,true)}}
      function logKeyLabel(log){var name=String(log.api_key_name||'').trim();var prefix=String(log.api_key_prefix||'').trim();if(!name&&!prefix)return'';if(name&&prefix)return'Key '+name+' · '+prefix+'…';if(name)return'Key '+name;return'Key '+prefix+'…'}
      function renderLogs(){if(!logs.length){$('logTable').innerHTML='<div class="empty">暂无调用记录。转发请求后会出现在这里。</div>';$('logPager').innerHTML=pageSizeSelectHTML('logPageSize',logLimit);return}$('logTable').innerHTML='<table><thead><tr><th>ID</th><th>模型</th><th>订阅</th><th>状态</th><th>Token</th></tr></thead><tbody>'+logs.map(function(log){var account=accounts.find(function(a){return String(a.id)===String(log.account_id)});var status=Number(log.http_error_code)||200;var tokens=Number(log.input_tokens||0)+Number(log.output_tokens||0)+Number(log.cache_creation_tokens||0)+Number(log.cache_read_tokens||0);return '<tr><td><div class="account-name">#'+escapeHTML(log.id)+' <span class="subtle">'+escapeHTML(formatDateTime(log.started_at))+'</span></div><div class="subtle">'+escapeHTML(log.source_ip||'')+(log.source_ip&&log.request_id?' · ':'')+escapeHTML(log.request_id||'')+'</div></td><td><div class="account-name">'+escapeHTML(log.model||log.provider_type||'—')+'</div><div class="subtle">'+escapeHTML(log.url||'')+'</div></td><td>'+escapeHTML(account?account.name:('订阅 '+(log.account_id||'—')))+'</td><td><span class="badge '+statusClass(status)+'">'+status+'</span></td><td>'+formatNumber(tokens)+'</td></tr>'}).join('')+'</tbody></table>';var from=logTotal?logOffset+1:0;var to=Math.min(logOffset+logs.length,logTotal);$('logPager').innerHTML=pageSizeSelectHTML('logPageSize',logLimit)+'<span>'+from+'-'+to+' / '+formatNumber(logTotal)+'</span><button class="btn" type="button" id="logPrev"'+(logOffset<=0?' disabled':'')+'>上一页</button><button class="btn" type="button" id="logNext"'+(logOffset+logLimit>=logTotal?' disabled':'')+'>下一页</button>'}
      function formatLogJSON(value){if(!value)return'';try{return JSON.stringify(JSON.parse(value),null,2)}catch(e){return String(value)}}
      function formatLogHeaders(value){if(!value)return'';try{var parsed=JSON.parse(value);if(!parsed||typeof parsed!=='object'||Array.isArray(parsed))return String(value);return Object.keys(parsed).map(function(key){var vals=parsed[key];if(!Array.isArray(vals))vals=[vals];return vals.map(function(item){return key+': '+item}).join('\n')}).filter(Boolean).join('\n')}catch(e){return String(value)}}
