      function fillAPIKeyAccountOptions(selected){var filter=$('keyAccountFilter').value;$('apiKeyAccount').innerHTML=accounts.map(function(a){return '<option value="'+a.id+'"'+(String(a.id)===String(selected)?' selected':'')+'>'+escapeHTML(a.name)+' · '+escapeHTML(a.provider)+'</option>'}).join('');$('keyAccountFilter').innerHTML='<option value="">全部订阅</option>'+accounts.map(function(a){return '<option value="'+a.id+'">'+escapeHTML(a.name)+'</option>'}).join('');if(filter)$('keyAccountFilter').value=filter}
      function renderAPIKeys(){fillAPIKeyAccountOptions($('apiKeyAccount').value);var query=$('keySearch').value.trim().toLowerCase();var accountID=$('keyAccountFilter').value;var filtered=keys.filter(function(k){var account=accounts.find(function(a){return String(a.id)===String(k.account_id)});var label=(account?(account.name+' '+account.provider):'')+' '+k.id;return(!accountID||String(k.account_id)===accountID)&&(!query||label.toLowerCase().includes(query))});if(!filtered.length){$('keyTable').innerHTML='<div class="empty">暂无 API Key。先接入订阅，再在这里签发。</div>';return}$('keyTable').innerHTML='<table><thead><tr><th>Key ID</th><th>订阅</th><th>平台</th><th>创建时间</th><th style="text-align:right">操作</th></tr></thead><tbody>'+filtered.map(function(k){var account=accounts.find(function(a){return String(a.id)===String(k.account_id)});return '<tr><td><div class="account-name">'+escapeHTML(k.id)+'</div><div class="key subtle">明文仅在签发成功时显示</div></td><td>'+escapeHTML(account?account.name:('订阅 '+k.account_id))+'</td><td><div class="provider-name">'+providerIcon(account&&account.provider||'')+escapeHTML(account&&account.provider||'—')+'</div></td><td class="subtle">'+formatTime(k.created_at)+'</td><td><div class="actions">'+iconActionButton('delete',k.id,'删除','trash','btn-danger')+'</div></td></tr>'}).join('')+'</tbody></table>'}
      function closeAPIKeyForm(){editingKeyID=0;$('apiKeyFormModal').hidden=true}
      function openCreateAPIKey(){if(!accounts.length){toast('请先接入一个订阅账号',true);return}$('apiKeyForm').reset();editingKeyID=0;fillAPIKeyAccountOptions('');$('deleteAPIKeyButton').hidden=true;$('apiKeyAccount').disabled=false;$('apiKeyFormTitle').textContent='签发 API Key';$('saveAPIKeyButton').textContent='签发 Key';$('apiKeyFormModal').hidden=false;$('apiKeyValidDays').focus()}
