      async function saveAPIKey(event){event.preventDefault();var button=$('saveAPIKeyButton');button.disabled=true;try{if(editingKeyID){toast('当前 API 只支持删除 API Key，不支持编辑',true);return}var accountID=$('apiKeyAccount').value;if(!accountID){toast('请选择订阅',true);return}var validDays=Number($('apiKeyValidDays').value)||0;if(validDays<0||!Number.isInteger(validDays)){toast('有效期必须是非负整数天',true);return}var result=await request('/api/keys',{method:'POST',body:JSON.stringify({account_id:accountID,valid_seconds:validDays*86400})});closeAPIKeyForm();showKey(result.key,'API Key 已签发',result);await loadData()}catch(e){toast(e.message,true)}finally{button.disabled=false}}
      function ccSwitchApp(provider){return({claude:'claude',codex:'codex',grok:'grokbuild'}[provider]||'claude')}
      function ccSwitchEndpoint(provider){var origin=location.origin;if(provider==='claude')return origin+'/claude';if(provider==='codex')return origin+'/codex/v1';if(provider==='grok')return origin+'/grok/v1';return origin}
      function openCCSwitch(key,plaintext){if(!key)return;if(!plaintext){toast('没有可用的 API Key，无法导入 CC Switch',true);return}var params=new URLSearchParams({resource:'provider',app:ccSwitchApp(key.provider),name:key.name||('UniSub '+key.subscription_name),endpoint:ccSwitchEndpoint(key.provider),homepage:location.origin,apiKey:plaintext});window.location.href='ccswitch://v1/import?'+params.toString();toast('已唤起 CC Switch')}
