      function renderUsers(){if(!isAdmin()){$('userTable').innerHTML='<div class="empty">只有管理员可以管理用户。</div>';return}if(!users.length){$('userTable').innerHTML='<div class="empty">暂无用户。</div>';return}var sortedUsers=users.slice().sort(function(a,b){return userName(a).localeCompare(userName(b),'zh-CN',{numeric:true,sensitivity:'base'})});$('userTable').innerHTML='<table><thead><tr><th>用户名</th><th>角色</th><th>状态</th><th style="text-align:right">操作</th></tr></thead><tbody>'+sortedUsers.map(function(u){var self=currentUser&&String(u.id)===String(currentUser.id);var enabled=userEnabled(u);return '<tr><td><div class="account-name">'+escapeHTML(userName(u))+(self?' <span class="subtle">当前</span>':'')+'</div></td><td>'+roleLabel(u.role)+'</td><td><span class="badge '+(enabled?'ok':'off')+'">'+(enabled?'已启用':'已停用')+'</span></td><td><div class="actions"><button class="btn" type="button" data-user-action="reset-password" data-id="'+escapeHTML(u.id)+'">重置密码</button><button class="btn" type="button" data-user-action="role" data-id="'+escapeHTML(u.id)+'" '+(self?'disabled':'')+'>'+(u.role==='admin'?'设为成员':'设为管理员')+'</button><button class="btn" type="button" data-user-action="toggle" data-id="'+escapeHTML(u.id)+'" '+(self?'disabled':'')+'>'+(enabled?'停用':'启用')+'</button><button class="btn btn-danger" type="button" data-user-action="delete" data-id="'+escapeHTML(u.id)+'" '+(self?'disabled':'')+'>删除</button></div></td></tr>'}).join('')+'</tbody></table>'}
