      function openResetPasswordModal(user){if(!user)return;resettingUserID=user.id;$('resetPasswordForm').reset();$('resetPasswordUsername').textContent=userName(user);$('resetPasswordModal').hidden=false;$('resetPasswordValue').focus()}
