      async function userAction(event){var button=event.target.closest('[data-user-action]');if(!button||button.disabled)return;var user=users.find(function(item){return String(item.id)===String(button.dataset.id)});if(!user)return;var action=button.dataset.userAction;try{if(action==='reset-password'){openResetPasswordModal(user);return}if(action==='role'){await request('/api/users/'+encodeURIComponent(user.id),{method:'PUT',body:JSON.stringify({role:user.role==='admin'?'user':'admin'})});toast('角色已更新');await loadData();return}if(action==='toggle'){await request('/api/users/'+encodeURIComponent(user.id),{method:'PUT',body:JSON.stringify({enabled:!userEnabled(user)})});toast(userEnabled(user)?'用户已停用':'用户已启用');await loadData();return}if(action==='delete'){if(!confirm('确定删除用户 '+userName(user)+' ？'))return;await request('/api/users/'+encodeURIComponent(user.id),{method:'DELETE'});toast('用户已删除');await loadData()}}catch(e){toast(e.message,true)}}
